def parse_csv_line(line: str) -> list[str]:
    fields: list[str] = []
    i = 0
    n = len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("unclosed quoted field")
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    buf.append(line[i])
                    i += 1
            if i < n and line[i] != ',':
                raise ValueError("unexpected characters after closing quote")
            fields.append(''.join(buf))
            if i >= n:
                return fields
            i += 1  # skip comma
        else:
            j = i
            while j < n and line[j] != ',':
                j += 1
            fields.append(line[i:j])
            if j >= n:
                return fields
            i = j + 1
