def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be positive")
    words = text.split()
    if not words:
        return []
    lines = []
    current = ''
    for word in words:
        while len(word) > width:
            if current:
                lines.append(current)
                current = ''
            lines.append(word[:width])
            word = word[width:]
        if current:
            if len(current) + 1 + len(word) <= width:
                current += ' ' + word
            else:
                lines.append(current)
                current = word
        else:
            current = word
    if current:
        lines.append(current)
    return lines
