import re

_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?'
    r'(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
)

def _parse(version: str):
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f'invalid semver: {version!r}')
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    ids = pre.split('.') if pre else []
    parsed = []
    for ident in ids:
        if ident.isdigit():
            parsed.append((0, int(ident), ''))
        else:
            parsed.append((1, 0, ident))
    return (major, minor, patch), parsed

def _cmp(x, y):
    return (x > y) - (x < y)

def semver_compare(a: str, b: str) -> int:
    core_a, pre_a = _parse(a)
    core_b, pre_b = _parse(b)
    core = _cmp(core_a, core_b)
    if core != 0:
        return core
    if pre_a == pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1
    for x, y in zip(pre_a, pre_b):
        if x != y:
            return _cmp(x, y)
    return _cmp(len(pre_a), len(pre_b))
