def eval_expr(s: str) -> int:
    i = 0
    n = len(s)

    def skip():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            skip()
            if i < n and s[i] in '+-':
                op = s[i]; i += 1
                rhs = parse_term()
                val = val + rhs if op == '+' else val - rhs
            else:
                return val

    def parse_term():
        nonlocal i
        val = parse_factor()
        while True:
            skip()
            if i < n and s[i] in '*/':
                op = s[i]; i += 1
                rhs = parse_factor()
                if op == '*':
                    val *= rhs
                else:
                    q = abs(val) // abs(rhs)
                    val = q if (val < 0) == (rhs < 0) else -q
            else:
                return val

    def parse_factor():
        nonlocal i
        skip()
        if i >= n:
            raise ValueError('unexpected end')
        if s[i] == '-':
            i += 1
            return -parse_factor()
        if s[i] == '+':
            i += 1
            return parse_factor()
        if s[i] == '(':
            i += 1
            val = parse_expr()
            skip()
            if i >= n or s[i] != ')':
                raise ValueError('missing )')
            i += 1
            return val
        j = i
        while i < n and s[i].isdigit():
            i += 1
        if i == j:
            raise ValueError('bad token')
        return int(s[j:i])

    result = parse_expr()
    skip()
    if i != n:
        raise ValueError('trailing input')
    return result
