    if seconds < 0:
        raise ValueError("seconds must be non-negative")
    units = [
        (365 * 86400, 'year'),
        (86400, 'day'),
        (3600, 'hour'),
        (60, 'minute'),
        (1, 'second'),
    ]
    parts = []
    for value, name in units:
        n, seconds = divmod(seconds, value)
        if n:
            parts.append(f"{n} {name}{'s' if n != 1 else ''}")
    if not parts:
        return 'now'
    if len(parts) == 1:
        return parts[0]
    return ', '.join(parts[:-1]) + ' and ' + parts[-1]
