def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    result = dict(balances)
    rejected = []
    for t in transfers:
        frm, to, amount = t["from"], t["to"], t["amount"]
        if frm not in result or to not in result:
            rejected.append(t["id"])
        elif frm == to:
            rejected.append(t["id"])
        elif isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            rejected.append(t["id"])
        elif result[frm] - amount < 0:
            rejected.append(t["id"])
        else:
            result[frm] -= amount
            result[to] += amount
