def glob_match(pattern: str, s: str) -> bool:
    pi = si = 0
    star = -1
    star_si = 0
    n, m = len(pattern), len(s)
    while si < m:
        if pi < n and pattern[pi] == '*':
            star = pi
            star_si = si
            pi += 1
        elif pi < n and pattern[pi] == '?':
            pi += 1
            si += 1
        elif pi < n and pattern[pi] == '[':
            j = pi + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                # unterminated: literal '['
                if pattern[pi] == s[si]:
                    pi += 1
                    si += 1
                elif star != -1:
                    star_si += 1
                    si = star_si
                    pi = star + 1
                else:
                    return False
                continue
            neg = False
            k = pi + 1
            if pattern[k] == '!':
                neg = True
                k += 1
            first = True
            matched = False
            while k < j or (first and k == j and pattern[k:k+1] == ']'):
                if first and pattern[pi+1] == '!' and k == pi + 2 and pattern[k] == ']':
                    break
                first = False
                if pattern[k] == ']' and k > pi + (2 if neg else 1):
                    break
                if k + 2 < j and pattern[k+1] == '-':
                    if pattern[k] <= s[si] <= pattern[k+2]:
                        matched = True
                    k += 3
                else:
                    if pattern[k] == s[si]:
                        matched = True
                    k += 1
            if matched != neg:
                pi = j + 1
                si += 1
            elif star != -1:
                star_si += 1
                si = star_si
                pi = star + 1
            else:
                return False
        elif pi < n and pattern[pi] == s[si]:
            pi += 1
            si += 1
        elif star != -1:
            star_si += 1
            si = star_si
            pi = star + 1
        else:
            return False
    while pi < n and pattern[pi] == '*':
        pi += 1
    return pi == n
```

The bracket parsing above is fiddly; here is a cleaner rewrite using a helper that parses one bracket class and returns its end index:

```python
def glob_match(pattern: str, s: str) -> bool:
    def parse_class(p, i):
        # pattern[i] == '['; returns (ok, matched, next_index) or None if unterminated
        j = i + 1
        neg = False
        if j < len(p) and p[j] == '!':
            neg = True
            j += 1
        items = []
        if j < len(p) and p[j] == ']':
            items.append(']')
            j += 1
        while j < len(p) and p[j] != ']':
            if j + 2 < len(p) and p[j+1] == '-' and p[j+2] != ']':
                items.append((p[j], p[j+2]))
                j += 3
            else:
                items.append(p[j])
                j += 1
        if j >= len(p):
            return None
        return (neg, items, j + 1)

    def class_matches(items, neg, c):
        hit = False
        for it in items:
            if isinstance(it, tuple):
                if it[0] <= c <= it[1]:
                    hit = True
                    break
            elif it == c:
                hit = True
                break
        return hit != neg

    n, m = len(pattern), len(s)
    pi = si = 0
    star = -1
    star_si = 0
    while si < m:
        if pi < n and pattern[pi] == '*':
            star = pi
            star_si = si
            pi += 1
        elif pi < n and pattern[pi] == '?':
            pi += 1
            si += 1
        elif pi < n and pattern[pi] == '[':
            r = parse_class(pattern, pi)
            if r is None:
                if pattern[pi] == s[si]:
                    pi += 1
                    si += 1
                elif star != -1:
                    star_si += 1
                    si = star_si
                    pi = star + 1
                else:
                    return False
            elif class_matches(r[1], r[0], s[si]):
                pi = r[2]
                si += 1
            elif star != -1:
                star_si += 1
                si = star_si
                pi = star + 1
            else:
                return False
        elif pi < n and pattern[pi] == s[si]:
            pi += 1
            si += 1
        elif star != -1:
            star_si += 1
            si = star_si
            pi = star + 1
        else:
            return False
    while pi < n and pattern[pi] == '*':
        pi += 1
    return pi == n
```

