def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    new_balances = dict(balances)
    rejected = []

    for transfer in transfers:
        transfer_id = transfer["id"]
        source = transfer["from"]
        target = transfer["to"]
        amount = transfer["amount"]

        if (
            source not in new_balances
            or target not in new_balances
            or source == target
            or type(amount) is not int
            or amount <= 0
            or new_balances[source] < amount
        ):
            rejected.append(transfer_id)
            continue

        new_balances[source] -= amount
        new_balances[target] += amount

    return {"balances": new_balances, "rejected": rejected}
