    rejected = []

    for transfer in transfers:
        transfer_id = transfer.get("id")
        sender = transfer.get("from")
        receiver = transfer.get("to")
        amount = transfer.get("amount")

        if sender not in new_balances or receiver not in new_balances:
            rejected.append(transfer_id)
            continue

        if sender == receiver:
            rejected.append(transfer_id)
            continue

        if not (isinstance(amount, int) and not isinstance(amount, bool) and amount > 0):
            rejected.append(transfer_id)
            continue

        if new_balances[sender] - amount < 0:
            rejected.append(transfer_id)
            continue

        new_balances[sender] -= amount
        new_balances[receiver] += amount

    return {"balances": new_balances, "rejected": rejected}
