```python
def parse_query(qs: str) -> dict[str, list[str]]:
    hexdigits = '0123456789abcdefABCDEF'

    def decode(s: str) -> str:
        out = bytearray()
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == '+':
                out.append(0x20)
                i += 1
            elif ch == '%':
                if i + 2 >= n:
                    raise ValueError(f"invalid percent escape in {s!r}")
                h = s[i + 1:i + 3]
                if any(c not in hexdigits for c in h):
                    raise ValueError(f"invalid percent escape in {s!r}")
                out.append(int(h, 16))
                i += 3
            else:
                out.extend(ch.encode('utf-8'))
                i += 1
        return out.decode('utf-8')

    result: dict[str, list[str]] = {}
    for pair in qs.split('&'):
        if pair == '':
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        k = decode(key)
        v = decode(value)
        result.setdefault(k, []).append(v)
    return result
