import urllib.parse

def _decode_component(comp: str) -> str:
    # Replace '+' with space before percent-decoding
    comp = comp.replace('+', ' ')
    # Perform percent-decoding with strict handling
    # urllib.parse.unquote_to_bytes returns bytes; we then decode UTF-8
    try:
        raw = urllib.parse.unquote_to_bytes(comp)
    except Exception as e:
        raise ValueError("Invalid percent-encoding") from e
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError("Invalid UTF-8 sequence in percent-encoding") from e

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result

    pairs = qs.split('&')
    for pair in pairs:
        if pair == '':
            continue  # skip empty pairs
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        try:
            dec_key = _decode_component(key)
            dec_val = _decode_component(value)
        except Exception as exc:
            # Propagate as ValueError per spec
            raise ValueError(str(exc)) from exc

        result.setdefault(dec_key, []).append(dec_val)
    return result
