import urllib.parse
import re

_percent_pat = re.compile(r'%[0-9A-Fa-f]{2}')

def _decode_component(comp: str) -> str:
    # Replace '+' with space before percent-decoding
    comp = comp.replace('+', ' ')
    # Validate percent-encodings: every '%' must be followed by two hex digits
    i = 0
    length = len(comp)
    while i < length:
        if comp[i] == '%':
            if i + 2 >= length or not re.fullmatch(r'[0-9A-Fa-f]{2}', comp[i+1:i+3]):
                raise ValueError(f"Invalid percent-encoding at position {i}: '{comp[i:]}'")
            i += 3
        else:
            i += 1
    # Perform percent-decoding to bytes, then decode UTF-8
    raw = urllib.parse.unquote_to_bytes(comp)
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError("Invalid UTF-8 sequence in percent-encoding") from e

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result

    for pair in qs.split('&'):
        if pair == '':
            continue  # skip empty pairs
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        dec_key = _decode_component(key)
        dec_val = _decode_component(value)
        result.setdefault(dec_key, []).append(dec_val)
