**Corrected Solution**

```python
from copy import deepcopy
from typing import Dict, List, Any

def apply_transfers(balances: Dict[str, int], transfers: List[Dict[str, Any]]) -> Dict[str, Any]:
    # Work on a copy to avoid mutating the input
    final_balances = deepcopy(balances)
    rejected: List[str] = []

    for tr in transfers:
        tr_id = tr.get("id")
        src = tr.get("from")
        dst = tr.get("to")
        amt = tr.get("amount")

        # Assume invalid until all checks pass
        invalid = False

        # 1. Both accounts must exist and be different
        if src not in final_balances or dst not in final_balances or src == dst:
            invalid = True
        # 2. Amount must be a positive int (bools are excluded)
        elif not isinstance(amt, int) or isinstance(amt, bool) or amt <= 0:
            invalid = True
        # 3. Sender must have enough balance
        elif final_balances[src] < amt:
            invalid = True

        if invalid:
            rejected.append(tr_id)
            continue

        # Apply the valid transfer
        final_balances[src] -= amt
        final_balances[dst] += amt

    return {"balances": final_balances, "rejected": rejected}
```

