import urllib.parse

def _decode_component(comp: str) -> str:
    # Replace '+' with space before percent-decoding
    plus_replaced = comp.replace('+', ' ')
    # Percent-decode, enforcing valid UTF-8 and valid hex
    try:
        return urllib.parse.unquote_to_bytes(plus_replaced).decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError('Invalid UTF-8 sequence') from e
    except ValueError as e:  # raised by unquote_to_bytes for bad %XX
        raise ValueError('Invalid percent-encoding') from e

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result

    pairs = qs.split('&')
    for pair in pairs:
        if not pair:
            continue  # skip empty pair

        if '=' in pair:
            key_raw, value_raw = pair.split('=', 1)
        else:
            key_raw, value_raw = pair, ''

        if key_raw == '':
            raise ValueError('Empty key is not allowed')

        key = _decode_component(key_raw)
        value = _decode_component(value_raw)

        result.setdefault(key, []).append(value)

    return result
