import re

_percent_invalid_re = re.compile(r'%(?![0-9A-Fa-f]{2})')

def _decode_component(comp: str) -> str:
    # Replace '+' with space before processing percent-escapes
    comp = comp.replace('+', ' ')
    # Validate percent-escapes
    if _percent_invalid_re.search(comp):
        raise ValueError('Invalid percent-encoding')
    # Decode percent-escapes as bytes and then UTF-8
    try:
        # Percent-decode to bytes
        bytes_seq = bytes(int(comp[i+1:i+3], 16) for i in range(0, len(comp)) if comp[i] == '%')
        # Build the byte string while also handling literal characters
        # We'll use urllib.parse.unquote_to_bytes style manually for clarity
        # Simpler: use urllib.parse.unquote_to_bytes after validation
        import urllib.parse
        return urllib.parse.unquote_to_bytes(comp).decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError('Invalid UTF-8 sequence') from e

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result

    for pair in qs.split('&'):
        if not pair:
            continue  # skip empty pairs

        if '=' in pair:
            key_raw, value_raw = pair.split('=', 1)
        else:
            key_raw, value_raw = pair, ''

        if key_raw == '':
            raise ValueError('Empty key is not allowed')

        key = _decode_component(key_raw)
        value = _decode_component(value_raw)

        result.setdefault(key, []).append(value)

    return result
